/* Recovered RPV3 companion growth wire and exact RPV2 migration.
 * Runtime callers must retain EXP/job state when changing HP or SP. */
#ifndef MYRO_COMPANION_PROGRESS200_H
#define MYRO_COMPANION_PROGRESS200_H
#include "npc_state55.h"
#define PARTY_PROGRESS_BYTES200 640u
#define PARTY_PROGRESS_KEY200 UINT64_C(0xeca20000f219bc63)
static const unsigned partyInitialJobs200[19]={7,1,2,10,3,18,12,4,14,15,16,19,20,40,41,42,43,44,45};
typedef struct{unsigned level,exp,jobLevel,jobExp,job,hp,sp;}PartyGrowth200;
static void party_progress_empty200(unsigned char*out){memset(out,0,640);memcpy(out,"RPV3",4);out[4]=1;}
static int party_growth_valid200(const PartyGrowth200*p){return p->level>=1&&p->level<=250&&p->exp<=INT_MAX&&p->jobLevel>=1&&p->jobLevel<=99&&p->jobExp<=INT_MAX&&p->job<46&&p->hp<=2000000000u&&p->sp<=2000000000u;}
static void party_growth_read200(const unsigned char*p,PartyGrowth200*out){out->level=npc_state_u32_55(p);out->exp=npc_state_u32_55(p+4);out->jobLevel=npc_state_u32_55(p+8);out->jobExp=npc_state_u32_55(p+12);out->job=npc_state_u32_55(p+16);out->hp=npc_state_u32_55(p+20);out->sp=npc_state_u32_55(p+24);}
static int party_progress_valid200(const unsigned char*b,int checksum){if(memcmp(b,"RPV3",4)||npc_state_u32_55(b+4)!=1||npc_state_u32_55(b+8)>=(1u<<19)||npc_state_u32_55(b+12)>36||(checksum&&npc_state_u32_55(b+636)!=crc32(0,b,636)))return 0;for(unsigned i=624;i<636;i++)if(b[i])return 0;unsigned mask=npc_state_u32_55(b+8);for(unsigned i=0;i<19;i++){const unsigned char*p=b+16+i*32;PartyGrowth200 m;party_growth_read200(p,&m);if(mask&(1u<<i)){if(!party_growth_valid200(&m)||npc_state_u32_55(p+28))return 0;}else for(unsigned j=0;j<32;j++)if(p[j])return 0;}return 1;}
static int party_progress_put200(unsigned char*b,unsigned id,const PartyGrowth200*p){if(id>=19||!party_growth_valid200(p))return 0;unsigned at=16+id*32;unsigned v[]={p->level,p->exp,p->jobLevel,p->jobExp,p->job,p->hp,p->sp,0};for(unsigned i=0;i<8;i++)npc_state_put32_55(b+at+i*4,v[i]);npc_state_put32_55(b+8,npc_state_u32_55(b+8)|(1u<<id));return 1;}
/* 1=loaded/migrated, 0=absent, -1=invalid. Migration does not write storage. */
static int party_progress_decode200(const unsigned char*input,unsigned bytes,unsigned char*out){if(!bytes){party_progress_empty200(out);return 0;}if(bytes==640){if(!party_progress_valid200(input,1))return-1;memcpy(out,input,640);return 1;}if(bytes!=256||memcmp(input,"RPV2",4)||npc_state_u32_55(input+4)!=1||npc_state_u32_55(input+8)>=(1u<<19)||npc_state_u32_55(input+252)!=crc32(0,input,252))return-1;for(unsigned i=240;i<252;i++)if(input[i])return-1;unsigned mask=npc_state_u32_55(input+8);for(unsigned i=0;i<19;i++){const unsigned char*p=input+12+i*12;unsigned level=npc_state_u32_55(p),hp=npc_state_u32_55(p+4),sp=npc_state_u32_55(p+8);if(mask&(1u<<i)){if(!level||level>250||hp>2000000000u||sp>2000000000u)return-1;}else if(level||hp||sp)return-1;}party_progress_empty200(out);for(unsigned i=0;i<19;i++)if(mask&(1u<<i)){const unsigned char*p=input+12+i*12;PartyGrowth200 m={npc_state_u32_55(p),0,2,0,partyInitialJobs200[i],npc_state_u32_55(p+4),npc_state_u32_55(p+8)};if(!party_progress_put200(out,i,&m))return-1;}return 1;}
static int party_progress_load200(const NpcState55*s,unsigned char*out){if(!s)return-1;const NpcVariable55*v=npc_state_get55(s,PARTY_PROGRESS_KEY200,0);if(!v)return party_progress_decode200(NULL,0,out);if(v->kind!=NPC_STATE_STRING_KIND55||(v->length!=512&&v->length!=1280))return-1;unsigned bytes=v->length/2;unsigned char b[640];for(unsigned i=0;i<bytes;i++){unsigned n=0;for(unsigned j=0;j<2;j++){unsigned x=(unsigned char)v->text[i*2+j];if(x>='0'&&x<='9')x-='0';else if(x>='a'&&x<='f')x=x-'a'+10;else return-1;n=n*16+x;}b[i]=(unsigned char)n;}return party_progress_decode200(b,bytes,out);}
static int party_progress_commit200(NpcState55*s,const unsigned char*b){if(!s||!party_progress_valid200(b,0))return 0;unsigned char raw[640];char text[1281];memcpy(raw,b,640);npc_state_put32_55(raw+636,crc32(0,raw,636));static const char hex[]="0123456789abcdef";for(unsigned i=0;i<640;i++){text[i*2]=hex[raw[i]>>4];text[i*2+1]=hex[raw[i]&15];}text[1280]=0;return npc_state_set_text55(s,PARTY_PROGRESS_KEY200,0,text,1280);}
#endif
